---parse.js---
/** The task-file parser: directives to tasks, with the failures the specification words. */

const NAME = /^[A-Za-z0-9_.-]+$/

/** One refusal of an input line, carrying the 1-based line it was read from, or 0 when it names none. */
export class ParseError extends Error {
  /**
   * @param {number} line - the 1-based input line, or 0 when the failure names no line.
   * @param {string} message - the message the specification words, without the `error: ` prefix.
   */
  constructor(line, message) {
    super(message)
    this.name = 'ParseError'
    this.line = line
  }
}

/** Whether a word is a usable task name. */
function isName(word) {
  return NAME.test(word)
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Parse a task file into its tasks.
 * @param {string[]} lines - the input lines.
 * @returns {Map<string, {name: string, command: string, needs: string[]}>} the tasks by name, in declaration order.
 */
export function parse(lines) {
  const tasks = new Map()
  const referenced = []
  const attachments = []
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words[0] === 'task') {
      if (words.length < 3) throw new ParseError(line, 'expected task <name> <word>...')
      const name = words[1]
      if (!isName(name)) throw new ParseError(line, `invalid task name ${name}`)
      if (tasks.has(name)) throw new ParseError(line, `task ${name} is declared twice`)
      tasks.set(name, { name, command: words.slice(2).join(' '), needs: [] })
    } else if (words[0] === 'needs') {
      if (words.length < 3) throw new ParseError(line, 'expected needs <name> <dependency>...')
      const [, name, ...values] = words
      if (!isName(name)) throw new ParseError(line, `invalid task name ${name}`)
      referenced.push(name)
      for (const value of values) {
        if (!isName(value)) throw new ParseError(line, `invalid task name ${value}`)
        referenced.push(value)
      }
      attachments.push({ name, values })
    } else {
      throw new ParseError(line, `unknown directive ${words[0]}`)
    }
  }
  for (const name of referenced) {
    if (!tasks.has(name)) throw new ParseError(0, `unknown task ${name}`)
  }
  for (const { name, values } of attachments) {
    const list = tasks.get(name).needs
    for (const value of values) {
      if (!list.includes(value)) list.push(value)
    }
  }
  return tasks
}

---graph.js---
/** Ordering the task graph. */

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose
 * dependencies have all been emitted. A cycle has no such task, so the order
 * stops early and leaves the tasks in it out.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 */
export function order(tasks) {
  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    if (ready.length === 0) break
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
---cli.js---
#!/usr/bin/env node
/** The command: `order`, `show <name>` and `digest <path>...`. */

import { existsSync, readFileSync } from 'node:fs'
import { digestBytes } from './digest.js'
import { order } from './graph.js'
import { parse, ParseError, splitLines } from './parse.js'

const USAGE = 'usage: cli.js order|show <name>|digest <path>...'

/** Report one failure the way the specification words it, and stop. */
function fail(message, code = 2) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(code)
}

/** One `show` field, with `-` standing for an empty list. */
function field(label, values) {
  return `${label}: ${values.length === 0 ? '-' : [...values].sort().join(' ')}`
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { order: 1, show: 2 }
if (mode === 'digest' ? argv.length < 2 : argv.length !== arity[mode]) fail(USAGE)

let tasks
try {
  tasks = parse(splitLines(readFileSync(0, 'utf8')))
} catch (error) {
  if (!(error instanceof ParseError)) throw error
  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
}

const out = []
if (mode === 'order') {
  for (const name of order(tasks)) out.push(name)
} else if (mode === 'show') {
  const task = tasks.get(argv[1])
  if (task === undefined) fail(`unknown task ${argv[1]}`)
  out.push(`${task.name}: ${task.command}`)
  out.push(field('needs', task.needs))
} else {
  for (const path of argv.slice(1)) {
    out.push(`${path} ${existsSync(path) ? digestBytes(readFileSync(path)) : 'missing'}`)
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
---digest.js---
/** FNV-1a over raw bytes, the digest the snapshot format records. */

const OFFSET = 0x811c9dc5
const PRIME = 16777619

/**
 * The 32-bit FNV-1a digest of a byte buffer as eight lowercase hex digits.
 * @param {Buffer} bytes - the bytes to digest.
 * @returns {string} the digest.
 */
export function digestBytes(bytes) {
  let hash = OFFSET >>> 0
  for (const byte of bytes) {
    hash = (hash ^ byte) >>> 0
    hash = Math.imul(hash, PRIME) >>> 0
  }
  return hash.toString(16).padStart(8, '0')
}

