 * walking each task's dependencies in ascending name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle's names, from the re-entered task back to a repeat of itself, or null.
 */
function findCycle(tasks) {
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, 'gray')
    stack.push(name)
    for (const dep of [...tasks.get(name).needs].sort()) {
      const depState = state.get(dep)
      if (depState === 'gray') {
        const start = stack.indexOf(dep)
        return [...stack.slice(start), dep]
      }
      if (depState === undefined) {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'black')
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (!state.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

