{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-ZedGyP/src/cli.js","content":"#!/usr/bin/env node
/** The command: `order`, `show <name>`, `files <name>`, `digest <path>...` and `plan <snapshot>`. */

import { existsSync, readFileSync } from 'node:fs'
import { digestBytes } from './digest.js'
import { CycleError, order } from './graph.js'
import { parse, ParseError, parseSnapshot, SnapshotError, splitLines } from './parse.js'

const USAGE = 'usage: cli.js order|show <name>|files <name>|digest <path>...|plan <snapshot>'

/** Report one failure the way the specification words it, and stop. */
function fail(message, code = 2) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(code)
}

/** One `show`/`files` field, with `-` standing for an empty list. */
function field(label, values) {
  return `${label}: ${values.length === 0 ? '-' : [...values].sort().join(' ')}`
}

/** The run order, refusing a cyclic graph the way the specification words it. */
function runOrder(tasks) {
  try {
    return order(tasks)
  } catch (error) {
    if (!(error instanceof CycleError)) throw error
    fail(error.message, 3)
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { order: 1, show: 2, files: 2, plan: 2 }
if (mode === 'digest' ? argv.length < 2 : argv.length !== arity[mode]) fail(USAGE)

let tasks
try {
  tasks = parse(splitLines(readFileSync(0, 'utf8')))
} catch (error) {
  if (!(error instanceof ParseError)) throw error
  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
}

const out = []
if (mode === 'order') {
  for (const name of runOrder(tasks)) out.push(name)
} else if (mode === 'show') {
  const task = tasks.get(argv[1])
  if (task === undefined) fail(`unknown task ${argv[1]}`)
  out.push(`${task.name}: ${task.command}`)
  out.push(field('needs', task.needs))
} else if (mode === 'files') {
  const task = tasks.get(argv[1])
  if (task === undefined) fail(`unknown task ${argv[1]}`)
  out.push(field('reads', task.reads))
  out.push(field('writes', task.writes))
} else if (mode === 'plan') {
  const snapshotPath = argv[1]
  let text
  try {
    text = readFileSync(snapshotPath, 'utf8')
  } catch {
    fail(`cannot read snapshot ${snapshotPath}`)
  }
  let digests
  try {
    digests = parseSnapshot(splitLines(text))
  } catch (error) {
    if (!(error instanceof SnapshotError)) throw error
    fail(`${snapshotPath}: line ${error.line}: ${error.message}`)
  }

  const runs = new Set()
  let ran = 0
  let skipped = 0
  for (const name of runOrder(tasks)) {
    const task = tasks.get(name)
    const watched = [...new Set([...task.reads, ...task.writes])].sort()
    let reason = null
    for (const path of watched) {
      if (!digests.has(path)) {
        reason = `new ${path}`
        break
      }
      if (!existsSync(path)) {
        reason = `missing ${path}`
        break
      }
      if (digestBytes(readFileSync(path)) !== digests.get(path)) {
        reason = `changed ${path}`
        break
      }
    }
    if (reason === null) {
      const runningDeps = task.needs.filter(dep => runs.has(dep)).sort()
      if (runningDeps.length > 0) reason = `needs ${runningDeps[0]}`
    }
    if (reason === null) {
      skipped += 1
      out.push(`skip ${name}`)
    } else {
      runs.add(name)
      ran += 1
      out.push(`run ${name} ${reason}`)
    }
  }
  out.push(`total run=${ran} skip=${skipped}`)
} else {
  for (const path of argv.slice(1)) {
    out.push(`${path} ${existsSync(path) ? digestBytes(readFileSync(path)) : 'missing'}`)
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

